"use strict";(()=>{chrome.runtime.onInstalled.addListener(()=>{chrome.sidePanel.setPanelBehavior({openPanelOnActionClick:!0}).then(()=>{console.log("[Career Agents Background] Side panel activated on action click.")}).catch(e=>{console.error("[Career Agents Background] Error setting panel behavior:",e)})});chrome.runtime.onMessage.addListener((e,r,n)=>(e.type==="PING_BACKGROUND"&&n({type:"PING_RESPONSE",payload:{active:!0}}),!0));})();
